using System.Text.Json;
using System.Text.Json.Nodes;
using ScenarioKernel.Adapters.Consumer;
using ScenarioKernel.Adapters.Graph;

var request = JsonNode.Parse(Console.ReadLine()!)!.AsObject();
var plan = request["plan"]!.AsObject();
var root = request["input"];
var physical = request["physicalCellIds"]!.AsArray().Select(x => x!.GetValue<string>()).ToHashSet(StringComparer.Ordinal);
var collections = new Dictionary<string, int>(StringComparer.Ordinal);
var engine = new SemanticTransformationEngine();
var cells = plan["canonicalGraph"]!["cells"]!.AsArray().Select(x => x!.AsObject()).ToDictionary(x => x["cellId"]!.GetValue<string>(), StringComparer.Ordinal);
async ValueTask<GraphProviderOutcome> Provider(JsonNode? input, GraphExecutionContext context, CancellationToken token)
{
    token.ThrowIfCancellationRequested();
    if (physical.Contains(context.CellId))
    {
        Console.WriteLine(new JsonObject {
            ["type"] = "invoke-provider", ["cellId"] = context.CellId,
            ["cellExecutionId"] = context.CellExecutionId, ["rootExecutionId"] = context.RootExecutionId,
            ["input"] = input?.DeepClone()
        }.ToJsonString());
        var reply = JsonNode.Parse((await Console.In.ReadLineAsync(token))!)!.AsObject();
        if (reply["error"] is JsonValue error) throw new InvalidOperationException(error.GetValue<string>());
        return new GraphProviderOutcome(reply["outcome"]?.DeepClone());
    }
    var expression = context.Configuration?["binding"]?["configuration"]?["expression"] as JsonObject ?? context.Configuration;
    if (expression?["op"] is not JsonValue operation)
    {
        if (cells[context.CellId]["execution"]?["authorityId"]?.GetValue<string>() == "mechanic:identity.v1") return new GraphProviderOutcome(input?.DeepClone(), "VALUE");
        throw new InvalidOperationException("UNDECLARED_EXECUTION_MECHANIC:" + context.CellId);
    }
    try
    {
        var entering = context.DecompositionInput ?? input;
        var outcome = engine.Transform(expression, entering, root);
        if (outcome is null) throw new InvalidOperationException("LEXICAL_BINDING_NOT_AVAILABLE_AT_CELL_ALTITUDE");
        if (new[] { "map", "flat-map", "filter", "find", "some", "every" }.Contains(operation.GetValue<string>(), StringComparer.Ordinal))
        {
            var occurrence = collections.GetValueOrDefault(context.CellId);
            collections[context.CellId] = occurrence + 1;
            var source = expression["from"] is JsonObject from ? engine.Transform(from, entering, root) as JsonArray : null;
            return new GraphProviderOutcome(outcome, occurrence < (source?.Count ?? 0) ? "CONTINUE" : "STOP");
        }
        return new GraphProviderOutcome(outcome);
    }
    catch (InvalidOperationException)
    {
        return new GraphProviderOutcome(input?.DeepClone(), "VALUE");
    }
}
var authorities = plan["bindingAuthorities"]!.AsArray().Select(x => x!.AsObject()).ToDictionary(x => x["id"]!.GetValue<string>(), StringComparer.Ordinal);
ValueTask<JsonNode?> ProjectBinding(string identity, JsonNode? value, CancellationToken token)
{
    token.ThrowIfCancellationRequested();
    return ValueTask.FromResult(engine.Transform(authorities[identity]["binding"]!["configuration"]!["expression"]!.AsObject(), value, root));
}
var providers = plan["realizationOverlay"]!["providerBindings"]!.AsArray()
    .Select(x => x!["providerProfileId"]!.GetValue<string>()).Distinct(StringComparer.Ordinal)
    .ToDictionary(identity => identity, _ => (GraphProvider)Provider, StringComparer.Ordinal);
var result = await new SemanticExecutionGraphScheduler(plan, providers, ProjectBinding).ExecuteAsync(root, request["rootExecutionId"]!.GetValue<string>());
Console.WriteLine(new JsonObject { ["type"] = "result", ["result"] = result }.ToJsonString());
